import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { CliError } from "../errors.ts";
import { localDatabaseArgs, outputTail, runTool, type WorkerTarget } from "../worker-target.ts";

// Migration files are generated by drizzle-kit (SQL plus meta/_journal.json)
// and applied by Wrangler, which records each applied file name in the
// migrations table. History compares those three sources; Wrangler stores
// names only, so an applied file edited afterwards cannot be detected.

export type MigrationHistory = {
	files: string[];
	applied: string[];
	pending: string[];
	problems: string[];
};

type Journal = { entries?: { tag?: unknown }[] };

export const migrationFiles = (target: WorkerTarget) =>
	existsSync(target.migrationsDir)
		? readdirSync(target.migrationsDir)
				.filter((name) => name.endsWith(".sql"))
				.sort()
		: [];

const journalFiles = (target: WorkerTarget) => {
	const path = join(target.migrationsDir, "meta", "_journal.json");
	if (!existsSync(path)) return undefined;
	try {
		const journal = JSON.parse(readFileSync(path, "utf8")) as Journal;
		return (journal.entries ?? []).map((entry) => `${String(entry.tag)}.sql`);
	} catch (error) {
		throw new CliError(`Cannot read ${path}: ${error instanceof Error ? error.message : String(error)}`);
	}
};

type D1Result = { results?: Record<string, unknown>[]; success?: boolean }[];

// Runs one read-only query on the target's local database through Wrangler.
const query = (target: WorkerTarget, sql: string) => {
	const result = runTool(target.dir, "wrangler", [
		"d1",
		"execute",
		...localDatabaseArgs(target),
		"--json",
		"--command",
		sql,
	]);
	const start = result.stdout.indexOf("[");
	let parsed: D1Result | undefined;
	try {
		parsed = start === -1 ? undefined : (JSON.parse(result.stdout.slice(start)) as D1Result);
	} catch {
		parsed = undefined;
	}
	if (result.status !== 0 || !parsed) {
		throw new CliError(`Could not read the local D1 database "${target.binding}":\n${outputTail(result.output)}`);
	}
	return parsed[0]?.results ?? [];
};

const appliedMigrations = (target: WorkerTarget) => {
	const table = target.migrationsTable;
	const exists = query(target, `SELECT name FROM sqlite_master WHERE type = 'table' AND name = '${table}'`);
	if (exists.length === 0) return [];
	return query(target, `SELECT name FROM "${table}" ORDER BY id`).map((row) => String(row.name));
};

export const readHistory = (target: WorkerTarget): MigrationHistory => {
	const files = migrationFiles(target);
	const journal = journalFiles(target);
	const applied = appliedMigrations(target);
	const problems: string[] = [];

	if (journal === undefined) {
		if (files.length > 0)
			problems.push("meta/_journal.json is missing, so the SQL files were not generated by drizzle-kit");
	} else {
		for (const file of files) if (!journal.includes(file)) problems.push(`${file} is not in meta/_journal.json`);
		for (const file of journal)
			if (!files.includes(file)) problems.push(`${file} is in meta/_journal.json but missing`);
	}
	for (const name of applied) if (!files.includes(name)) problems.push(`${name} was applied but its file is missing`);

	const pending = files.filter((file) => !applied.includes(file));
	const lastApplied = files.filter((file) => applied.includes(file)).at(-1);
	if (lastApplied !== undefined) {
		for (const file of pending) {
			if (file < lastApplied) problems.push(`${file} is pending but sorts before the applied ${lastApplied}`);
		}
	}
	return { files, applied, pending, problems };
};

export const historyError = (target: WorkerTarget, history: MigrationHistory) =>
	new CliError(
		`Migration history for "${target.binding}" does not match the files in ${target.migrationsDir}:\n${history.problems
			.map((problem) => `  - ${problem}`)
			.join("\n")}`,
		{
			hint: "Restore the missing or edited files from version control; never rewrite applied migrations. Add a new migration instead.",
		},
	);

export type ApplyResult = { applied: string[] };

// Checks history, applies pending migrations with Wrangler, then reads the
// history again: success means Wrangler succeeded and nothing is left pending.
export const applyMigrations = (target: WorkerTarget): ApplyResult => {
	const before = readHistory(target);
	if (before.problems.length > 0) throw historyError(target, before);
	if (before.pending.length === 0) return { applied: [] };

	const result = runTool(target.dir, "wrangler", ["d1", "migrations", "apply", ...localDatabaseArgs(target)]);
	const after = readHistory(target);
	const applied = after.applied.filter((name) => !before.applied.includes(name));
	if (result.status !== 0 || after.pending.length > 0 || after.problems.length > 0) {
		const failed = after.pending[0];
		const done = applied.length > 0 ? `Applied before the failure: ${applied.join(", ")}.\n` : "";
		throw new CliError(
			`Migration ${failed ?? "run"} failed and was rolled back; it is still pending.\n${done}${outputTail(result.output)}`,
			{ hint: "Fix the failing migration with a new migration file, then run `takebase migrate apply` again." },
		);
	}
	return { applied };
};

export const hasDrizzleConfig = (dir: string) =>
	["drizzle.config.ts", "drizzle.config.js", "drizzle.config.mjs"].some((file) => existsSync(join(dir, file)));

// Generates SQL from the Worker's Drizzle schema with its own drizzle-kit.
export const generateMigration = (target: WorkerTarget, name: string) => {
	if (!hasDrizzleConfig(target.dir)) {
		throw new CliError(`No drizzle.config.ts in ${target.dir}`, {
			hint: "Migrations are generated from a Worker's Drizzle schema; add drizzle.config.ts to this Worker first.",
		});
	}
	const before = migrationFiles(target);
	const result = runTool(target.dir, "drizzle-kit", ["generate", "--name", name]);
	if (result.status !== 0) throw new CliError(`drizzle-kit generate failed:\n${outputTail(result.output)}`);
	const created = migrationFiles(target).filter((file) => !before.includes(file));
	if (created.length === 0 && !/No schema changes/i.test(result.output)) {
		throw new CliError(`drizzle-kit wrote no migration into ${target.migrationsDir}`, {
			hint: "drizzle.config.ts `out` must be the D1 binding's migrations_dir in wrangler.jsonc.",
		});
	}
	return created;
};

export const readMigration = (target: WorkerTarget, file: string) =>
	readFileSync(join(target.migrationsDir, file), "utf8");
